public class Animacion extends Trabajo {
	//Atributo nuevo
    protected int fotogramas;

    // Constructor vacío
    public Animacion() {
		//Super trae los datos para abajo
        super();
        fotogramas = 0;
    }

    // CConstructor completo

    public Animacion(String codigo, String estudio,
                    String nombre, float horasEstimadas,
                    boolean diurno, int fotogramas) {

        super(codigo, estudio, nombre, horasEstimadas, diurno);

        this.fotogramas = fotogramas;
    }


    // Setter y getter de mi nuevo atributo (será una costumbre)

    public void setFotogramas(int newFotogramas) {
        fotogramas = newFotogramas;
    }

    public int getFotogramas() {
        return fotogramas;
    }


    // Calcular horas por fotogramas (0.02 * fotogramas)

    public float horasFotogramas() {

        return fotogramas * 0.02f;
    }


    // horas favcturables. 
	//Compara las horas estimadas con la horas fotogramas y devuelve la mayor. Esa se usará en los cálculos.

    public int horasFacturables() {

        float mayor;
        if (horasEstimadas > horasFotogramas()) {
            mayor = horasEstimadas;
        }
        else {
            mayor = horasFotogramas();
        }

        // Redondea hacia arriba el valor seleccionado. (Función techo, o "ceiling") Soy matemático, comprendo esto
        return (int) Math.ceil(mayor);
    }


    // Nuevo costo, este determina la tarifa vase + 15 * hora favturable.

    @Override
    public float calcularCosto() {

        float tarifaBase;
        // Tarifa base.
        if (diurno) {
            tarifaBase = 60.0f;
        }
        else {
            tarifaBase = 40.0f;
        }

        // Costo final
        return tarifaBase + (horasFacturables() * 15.0f);
    }


    // TIEMPO DE ENTREGA
    // Sobrescribe el metodo abstracto de Trabajo.
    //
    // Una animacion diurna tarda 24 horas.
    // Una animacion nocturna tarda 36 horas.

    @Override
    public int tiempoEntrega() {

        if (diurno) {
            return 24;
        }
        else {
            return 36;
        }
    }


    // MAXIMO DE INTENTOS
    // Sobrescribe el metodo abstracto de Trabajo.
    //
    // Una animacion normal permite hasta 3 intentos,
    // incluyendo la primera ejecucion.

    @Override
    public int maxIntentos() {

        return 3;
    }


    // OBTENER CATEGORIA
    // Sobrescribe el metodo abstracto de Trabajo.
    //
    // Devuelve el nombre de la categoria para que
    // Registro pueda identificarla en los reportes
    // sin utilizar instanceof.

    @Override
    public String getCategoria() {

        return "Animacion";
    }
}
